   233→  /** Attempt to restore session from stored credentials */
   234→  public static restoreSession = async (): Promise<boolean> => {
   235→    try {
   236→      const credentials = MatrixStorage.getLoginCredentials();
   237→
   238→      if (!credentials) return false;
   239→
   240→      await this.initialize(credentials.baseUrl);
   241→
   242→      if (!this.instance) throw new Error("Failed to initialize client");
   243→
   244→      // Create client with stored credentials
   245→      await this.instance.restoreSession({
   246→        accessToken: credentials.accessToken,
   247→        refreshToken: credentials.refreshToken,
   248→        userId: credentials.userId,
   249→        deviceId: credentials.deviceId,
   250→        homeserverUrl: credentials.baseUrl,
   251→        oidcData: undefined,
   252→        slidingSyncVersion: SlidingSyncVersion.Native,
   253→      });
   254→
   255→      // Verify the session is valid by making a server request
   256→      try {
   257→        this.profile = await this.instance.getProfile(credentials.userId);
   258→      } catch (error) {
   259→        console.warn("Session validation failed:", error);
   260→        throw new Error("Session is invalid or expired");
   261→      }
   262→
   263→      this.syncService = await this.instance.syncService().finish();
   264→
   265→      if (!this.syncService) {
   266→        throw new Error("Failed to initialize sync service");
   267→      }
   268→
   269→      await this.syncService.start();
   270→
   271→      // Update atoms so providers can react to the initialized service
   272→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   273→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   274→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   275→
   276→      return true;
   277→    } catch (error) {
   278→      console.warn("Failed to restore session:", error);
   279→
   280→      // Clear both credentials and crypto store to ensure clean state
   281→      MatrixStorage.clearLoginCredentials();
   282→      await this.clearCryptoStore();
   283→
   284→      // Reset the instance so it can be recreated fresh
   285→      this.instance = null;
   286→      this.syncService = null;
   287→
   288→      // Clear atoms
   289→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   290→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   291→
   292→      return false;
   293→    }
   294→  };
