  1632→  /** Enable recovery and get the recovery key
  1633→   * This will create a backup and return the recovery key that you MUST save */
  1634→  public static enableRecovery = async (passphrase?: string) => {
  1635→    if (!this.instance) throw new Error("Client not initialized");
  1636→
  1637→    const encryption = this.instance.encryption();
  1638→
  1639→    // Create a progress listener
  1640→    const progressListener: EnableRecoveryProgressListener = {
  1641→      onUpdate: (status) => {
  1642→        console.log("🔐 Recovery progress:", status);
  1643→      },
  1644→    };
  1645→
  1646→    // Enable recovery and get the key
  1647→    const recoveryKey = await encryption.enableRecovery(
  1648→      true,
  1649→      passphrase,
  1650→      progressListener,
  1651→    );
  1652→
  1653→    // Perform a full recover round-trip to verify all secrets are stored in
  1654→    // SSSS and the recovery state transitions to Enabled. The SDK's state
  1655→    // listener alone may not emit Enabled promptly, leaving state Incomplete.
  1656→    await encryption.recover(recoveryKey);
  1657→
  1658→    console.log("✅ Recovery enabled! Save your recovery key securely.");
  1659→    return recoveryKey;
  1660→  };
  1661→
  1662→  /** Reset the recovery key and get a new one
  1663→   * Use this if you lost your old recovery key*/
  1664→  public static resetRecoveryKey = async () => {
  1665→    if (!this.instance) throw new Error("Client not initialized");
  1666→
  1667→    const encryption = this.instance.encryption();
  1668→    const newRecoveryKey = await encryption.resetRecoveryKey();
  1669→
  1670→    // Perform a full recover round-trip after resetting to ensure all secrets
  1671→    // are verified under the new key and the state transitions to Enabled.
  1672→    // Without this, the SDK's recoveryStateListener may never emit Enabled,
  1673→    // leaving the state stuck at Incomplete indefinitely.
  1674→    await encryption.recover(newRecoveryKey);
  1675→
  1676→    console.log("✅ Recovery key reset! Save your new recovery key securely.");
  1677→    return newRecoveryKey;
  1678→  };
  1679→
  1680→  /** Recover using a recovery key
